        "data": "26/06/2024",
        "texto": "Não é infração penal adquirir, guardar, ter em depósito, transportar ou trazer consigo maconha para consumo pessoal (ilícito extrapenal, com advertência e medida educativa aplicadas pelo juiz, sem efeito penal); presume-se usuário quem tem até 40 g ou seis plantas-fêmeas, presunção relativa que a autoridade policial pode afastar fundamentadamente diante de indícios de tráfico."
